    // 找出数组中的回调函数，然后删除
    for (let i = 0; i < fns.length; i++) {
      	// 此处修改，可正常解绑 once 对应的函数
        if(fns[i] === callback || fns[i] === callback.once) {
            fns.splice(i, 1);
            break;
        }
    }
    // 如果删除回调函数后，数组为空，则删除该事件
    if (fns.length === 0) {
